#!/usr/bin/env python3
"""Autorenwerkzeug: Matthäusevangelium Kapitel 1–7 – Befunde, Deutungen, Grundsätze, Anwendungen, offene Fragen,
Beziehungen, Hintergrund zu Abschnitten, Kapitel-Zusammenfassungen und Studie; jeweils mit Züridüütsch-Lokalisierung.

Nicht hier geschrieben (bestehen schon und bleiben unverändert):
- Studieninhalte zum Vaterunser [[MAT.6.5-MAT.6.15]] (FIND-LP-…, INT-LP-…, BG-LP-…, STUDY-LP-0001; scripts/authoring/
  vaterunser.py) und die Zusammenfassung SUM-CH-MAT-006 (dort erzeugt; hier nur geprüft);
- Hintergrund zum ganzen Buch BG-MAT-BOOK-0001 (scripts/authoring/hintergrund_buecher.py);
- die Kontexte CTX-MAT-READERS-0085, CTX-GALILEE-0030 und CTX-HIST-SECOND-TEMPLE: sie werden nur verwendet. Der Kontext
  für write_study wird unverändert aus der Datei gelesen, damit write() nichts überschreibt.

Nummernraum dieses Werkzeugs: 1001–1999 (FIND-MAT-1…, INT-MAT-1…, BG-MAT-1… usw.); Studie STUDY-MAT-0002.

Abschnitte: Jede Aussage nennt den Versbereich, auf den sie sich bezieht; zugeordnet wird die kleinste vorhandene
Texteinheit (data/text-units/TU-MAT-…), die ihn ganz enthält, sonst die Kapiteleinheit.
Wortzählungen: per Skript nach den MACULA-Lemmata zum SBLGNT (data/annotations/MACULA-SBLGNT-MAT-0nn.json; für
Vergleiche MRK/LUK ebenso). Gezählt sind Wortvorkommen; Wendungen (z. B. «Reich der Himmel») als Folge der Lemmata
innerhalb von drei Wörtern. Wo Belege einer Bedeutung zugeordnet sind (z. B. «Vater» für Gott), ist das durch Durchsicht
der Stellen geschehen und vermerkt.

Aufruf: python3 scripts/authoring/matthaeus_study_a.py
KI-Entwurf (Claude) vom 2026-10-18 auf Wunsch von Andi Neck; keine fachliche Prüfung erfolgt.
"""
import json
import re
import sys
import pathlib

sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent))
from _lib import D  # noqa: E402
import _study  # noqa: E402

DATE = "2026-10-18"
_study.DATE = DATE
_study.AUTH = f"KI-Entwurf (Claude) vom {DATE} auf Wunsch von Andi Neck; keine fachliche Prüfung erfolgt."
_study.AUTH_GSW = (f"KI-Entwurf (Claude) vom {DATE}; aus dem Hochdeutschen in Züridüütsch gefasst; "
                   "Mundart noch nicht muttersprachlich geprüft.")

TAGS = ["TAG-MATTHEW"]
CHAPTERS = {1: "TU-MAT-001-001-025", 2: "TU-MAT-002-001-023", 3: "TU-MAT-003-001-017", 4: "TU-MAT-004-001-025",
            5: "TU-MAT-005-001-048", 6: "TU-MAT-006-001-034", 7: "TU-MAT-007-001-029"}
_UNITS = sorted(p.stem for p in (D / "text-units").rglob("TU-MAT-*.json"))


def U(ch, v1, v2=None):
    """Kleinste vorhandene Texteinheit, die Kapitel ch, Verse v1–v2 ganz enthält; sonst die Kapiteleinheit."""
    v2 = v2 or v1
    if ch not in CHAPTERS:
        raise SystemExit(f"Mt {ch} gehört nicht zu diesem Werkzeug")
    if ch == 6 and v1 >= 5 and v2 <= 15:
        raise SystemExit("Mt 6,5–15 gehört zur Vaterunser-Studie (vaterunser.py)")
    best = None
    for uid in _UNITS:
        m = re.fullmatch(r"TU-MAT-(\d{3})-(\d{3})-(\d{3})", uid)
        if m and int(m[1]) == ch and int(m[2]) <= v1 and int(m[3]) >= v2:
            if best is None or int(m[3]) - int(m[2]) < best[0]:
                best = (int(m[3]) - int(m[2]), uid)
    return best[1] if best else CHAPTERS[ch]


# Bestehender Kontext, unverändert übernommen (write() schreibt dann nichts)
CONTEXT = json.loads((D / "contexts" / "CTX-MAT-READERS-0085.json").read_text(encoding="utf-8"))
READERS = "CTX-MAT-READERS-0085"
GAL = "CTX-GALILEE-0030"
TEMPLE = "CTX-HIST-SECOND-TEMPLE"

MAC = "Zählung per Skript nach den MACULA-Lemmata zum SBLGNT."
MAC_G = "Zellig per Skript nach de MACULA-Lemmata zum SBLGNT."

