# Hintergrund: (id, Abschnitt, Stelle, Kontext, Konfidenz, Thema, Text, unsicher, Belege, Quellen, Fachwörter | Mundart)
BACKGROUND = [
 # Kapitel 1
 ("BG-MAT-1001", U(1, 1, 17), "MAT.1.1-MAT.1.17", TEMPLE, "probable", "Stammbäume in Bibel und Antike",
  "Stammbäume ordnen in der Bibel die Geschichte und begründen Zugehörigkeit (etwa [[GEN.5.1-GEN.5.32]]; [[RUT.4.18-RUT.4.22]]; [[1CH.1.1-1CH.3.24]]). Für Priester und Königshaus war die Abstammung wichtig: Nach dem Exil wurden Familien ohne Nachweis vom Priesterdienst ausgeschlossen ([[EZR.2.61-EZR.2.63]]), und Josephus beginnt seine Lebensbeschreibung mit seiner priesterlichen Herkunft, die er aus öffentlichen Verzeichnissen kenne. Antike Stammbäume konnten Glieder überspringen; «zeugen» und «Sohn» bezeichnen dann auch spätere Nachkommen. Lukas überliefert einen ganz anderen Stammbaum: aufsteigend bis zu Adam und Gott, über Davids Sohn Natan statt Salomo, mit Eli als Vater Josefs ([[LUK.3.23-LUK.3.38]]).",
  "Wie sich die beiden Stammbäume zueinander verhalten, ist ungeklärt. Schon Julius Africanus (3. Jh.) erklärte die Unterschiede mit einer Schwagerehe; andere vermuten bei Lukas die Linie Marias. Beides ist nicht belegbar.",
  ["GEN.5.1-GEN.5.32", "RUT.4.18-RUT.4.22", "1CH.1.1-1CH.3.24", "EZR.2.61-EZR.2.63", "LUK.3.23-LUK.3.38"],
  ["Josephus, Leben (Vita) 1–6", "Julius Africanus, Brief an Aristides (bei Eusebius, Kirchengeschichte 1,7)"],
  [("heb", "תּוֹלְדוֹת", "Geschlechterfolge, Entstehungsgeschichte", "tôlᵉḏôt"), ("grc", "γένεσις", "Ursprung, Entstehung; Geburt")],
  "Stammbäum i de Bible und i de Antike",
  "Stammbäum ordned i de Bible d Gschicht und begründed, wär dezueghört (öppe [[GEN.5.1-GEN.5.32]]; [[RUT.4.18-RUT.4.22]]; [[1CH.1.1-1CH.3.24]]). Für Prieschter und s Königshuus isch d Abstammig wichtig gsii: Nach em Exil sind Familie ohni Nachwiis vom Prieschterdienscht usgschlosse worde ([[EZR.2.61-EZR.2.63]]), und de Josephus fangt sini Läbesbeschriibig mit sinere prieschterliche Härkunft aa, won er us öffentliche Verzeichnis känni. Antiki Stammbäum händ Glider chöne überspringe; «zeuge» und «Sohn» bezeichned dänn au spööteri Nachkomme. De Lukas überliferet en ganz andere Stammbaum: ufstiigend bis zum Adam und zu Gott, über de Natan, en Sohn vom David, statt über de Salomo, und mit em Eli als Vatter vom Josef ([[LUK.3.23-LUK.3.38]]).",
  "Wie sich di beide Stammbäum zunenand verhalted, isch nöd klärt. Scho de Julius Africanus (3. Jh.) hät d Underschid mit ere Schwagerehe erklärt; anderi vermueted bim Lukas d Linie vo de Maria. Beides cha me nöd belegge.",
  ["Gschlächterfolg, Entstehigsgschicht", "Ursprung, Entstehig; Geburt"]),
 ("BG-MAT-1002", U(1, 18, 25), "MAT.1.18-MAT.1.19", GAL, "probable", "Verlobung und Ehe",
  "Eine jüdische Ehe wurde in zwei Schritten geschlossen. Mit der Verlobung (später qiddûšîn oder ʾērûsîn genannt) galt die Frau rechtlich als Ehefrau des Mannes: Untreue zählte als Ehebruch ([[DEU.22.23-DEU.22.24]]), und eine Trennung war nur durch Scheidung möglich. Erst später holte der Mann die Frau in sein Haus; nach der Mischna hatte eine Jungfrau dafür bis zu zwölf Monate Zeit. Mädchen wurden nach späteren Quellen oft jung verlobt, etwa mit zwölf bis vierzehn Jahren. Das erklärt, warum Josef schon «ihr Mann» heisst ([[MAT.1.19]]) und eine «heimliche» Scheidung erwägt, also eine ohne öffentliche Anklage.",
  "Die rabbinischen Quellen sind später (Mischna um 200 n. Chr.); wie weit sie die Bräuche im Galiläa des 1. Jahrhunderts wiedergeben, ist unsicher. Das Heiratsalter ist geschätzt.",
  ["DEU.22.23-DEU.22.24", "DEU.24.1", "MAT.1.18-MAT.1.25"], ["Mischna Ketubbot 5,2"],
  [("grc", "μνηστεύω", "verloben; verlobt sein"), ("heb", "קִדּוּשִׁין", "Verlobung, rechtlich bindende Eheschliessung", "qiddûšîn")],
  "Verlobig und Ee",
  "E jüdischi Ee isch i zwei Schritt gschlosse worde. Mit de Verlobig (spööter qiddûšîn oder ʾērûsîn gnännt) hät d Frau rächtlich als Eefrau vom Maa gulte: Untrüü hät als Eebruch zellt ([[DEU.22.23-DEU.22.24]]), und e Trännig isch nu dur e Scheidig möglich gsii. Erscht spööter hät de Maa d Frau i sis Huus gholt; nach de Mischna hät e Jungfrau defür bis zu zwölf Mönet Ziit ghaa. Meitli sind nach spöötere Quälle oft jung verlobt worde, öppe mit zwölf bis vierzää Jaar. Das erklärt, werum de Josef scho «ire Maa» heisst ([[MAT.1.19]]) und e «heimlichi» Scheidig überleit, also eini ohni öffentlichi Aaklag.",
  "D rabbinische Quälle sind spööter (Mischna um 200 n. Chr.); wie wiit si d Brüüch im Galiläa vom 1. Jaarhundert widergänd, isch unsicher. S Hüüraatsalter isch gschätzt.",
  ["verlobe; verlobt sii", "Verlobig, rächtlich bindendi Eeschlüüssig"]),
 ("BG-MAT-1003", U(1, 18, 25), "MAT.1.21-MAT.1.23", READERS, "probable", "Der Name Jesus und das Immanuel-Wort",
  "Jeschua, eine Kurzform von Jehoschua (Josua), war im 1. Jahrhundert ein häufiger Name; Josephus nennt mehrere Männer dieses Namens, darunter zwei Hohepriester. Der Name enthält den Gottesnamen und den Stamm «retten» (jāšaʿ); die Erklärung «denn er wird sein Volk retten» ([[MAT.1.21]]) beruht auf diesem hebräischen Wortspiel, das im Griechischen nicht zu sehen ist. Das Immanuel-Wort stammt aus der Zeit König Ahas’, als Aram und Israel um 734/733 v. Chr. Jerusalem bedrohten ([[ISA.7.1-ISA.7.16]]; [[2KI.16.5]]): Bevor ein bald geborenes Kind Gut und Böse unterscheiden kann, sollen die Feinde verschwunden sein. Die Septuaginta übersetzt das hebräische ʿalmāh («junge Frau») mit παρθένος; Matthäus zitiert diesen Wortlaut.",
  "Eine jüdische Auslegung von [[ISA.7.14]] auf den Messias ist vor den Christen nicht belegt.",
  ["ISA.7.1-ISA.7.16", "2KI.16.5", "MAT.1.21-MAT.1.23"], ["Josephus, Jüdische Altertümer 20,200; 20,213"],
  [("heb", "יֵשׁוּעַ", "Jeschua, Jesus", "yēšûaʿ"), ("heb", "עִמָּנוּ אֵל", "Immanuel: Gott (ist) mit uns", "ʿimmānû ʾēl"), ("heb", "עַלְמָה", "junge Frau (im heiratsfähigen Alter)", "ʿalmāh")],
  "De Name Jesus und s Immanuel-Wort",
  "Jeschua, e Churzform vo Jehoschua (Josua), isch im 1. Jaarhundert en hüüfige Name gsii; de Josephus nännt meereri Manne mit dem Name, drunder zwei Hohepriester. De Name hät de Gottesname und de Stamm «rette» (jāšaʿ) drin; d Erklärig «dänn er wird sis Volk rette» ([[MAT.1.21]]) beruet uf dem hebräische Wortspil, wo me im Griechische nöd gseet. S Immanuel-Wort stammt us de Ziit vom König Ahas, wo Aram und Israel um 734/733 v. Chr. Jerusalem bedroot händ ([[ISA.7.1-ISA.7.16]]; [[2KI.16.5]]): Bevor es Chind, wo bald gebore wird, Guet und Bös cha underscheide, söled d Find verschwunde sii. D Septuaginta übersetzt s hebräisch ʿalmāh («jungi Frau») mit παρθένος; de Matthäus zitiert dä Wortluut.",
  "E jüdischi Uuslegig vo [[ISA.7.14]] uf de Messias isch vor de Christe nöd belegt.",
  ["Jeschua, Jesus", "Immanuel: Gott (isch) mit üs", "jungi Frau (im hüüraatsfääige Alter)"]),
 # Kapitel 2
 ("BG-MAT-1004", U(2, 1, 12), "MAT.2.1-MAT.2.16", TEMPLE, "probable", "Herodes der Grosse",
  "Herodes, ein Idumäer, wurde 40 v. Chr. vom römischen Senat zum König von Judäa ernannt und herrschte ab 37 v. Chr. Er liess den Tempel prachtvoll erneuern und baute Festungen und Städte, darunter das Herodeion wenige Kilometer südöstlich von Betlehem. Zugleich war er misstrauisch und grausam: Er liess seine Frau Mariamne und drei seiner Söhne hinrichten. Der spätrömische Schriftsteller Macrobius überliefert den Spott des Augustus, es sei besser, das Schwein des Herodes zu sein als sein Sohn. Herodes starb nach den Angaben des Josephus wahrscheinlich 4 v. Chr. in Jericho. Josephus erzählt auch die Geburt des Mose mit einer Vorhersage an den Pharao, der darauf die Knaben töten lässt.",
  "Den Kindermord in Betlehem erwähnt keine andere Quelle; er passt zum Bild des Herodes bei Josephus, ist aber nicht bestätigt. Das Todesjahr 4 v. Chr. ist verbreitet, einige vertreten 1 v. Chr.",
  ["MAT.2.1-MAT.2.22"],
  ["Josephus, Jüdische Altertümer 14–17", "Josephus, Jüdische Altertümer 2,205–216 (Geburt des Mose)", "Josephus, Jüdischer Krieg 1", "Macrobius, Saturnalien 2,4,11"],
  [],
  "Herodes de Gross",
  "De Herodes, en Idumäer, isch 40 v. Chr. vom römische Senat zum König vo Judäa ernännt worde und hät ab 37 v. Chr. regiert. Er hät de Tämpel prächtig loo erneuere und Feschtige und Stedt baut, drunder s Herodeion es paar Kilometer südöschtlich vo Betlehem. Zuglich isch er misstrauisch und grausam gsii: Er hät sini Frau Mariamne und drüü vo sine Söön loo hiirichte. De spöötrömisch Schriftsteller Macrobius überliferet de Spott vom Augustus, es seg besser, s Säuli vom Herodes z sii als sin Sohn. De Herodes isch nach de Aagaabe vom Josephus wahrschiinli 4 v. Chr. z Jericho gstorbe. De Josephus verzellt au d Geburt vom Mose mit ere Vorhersag a de Pharao, wo druf d Buebe laat töte.",
  "De Chindermord z Betlehem erwäänt kei anderi Quälle; er passt zum Bild vom Herodes bim Josephus, isch aber nöd bestätiget. S Todesjaar 4 v. Chr. isch verbreitet, es paar vertreted 1 v. Chr.",
  []),
 ("BG-MAT-1005", U(2, 1, 12), "MAT.2.1-MAT.2.12", TEMPLE, "possible", "Sterndeuter und Stern",
  "Nach Herodot waren die Magier ein Stamm der Meder, aus dem Priester und Traumdeuter kamen; später hiessen so Kundige der Sterne und der Weisheit aus Persien und Babylonien, abwertend auch Zauberer ([[ACT.13.6-ACT.13.8]]). In Babylonien wurde Sternkunde seit Jahrhunderten gepflegt, und in der Antike glaubte man verbreitet, dass Sterne die Geburt von Herrschern anzeigen. In Israel kannte man das Wort Bileams, eines Sehers «aus den Bergen des Ostens» ([[NUM.23.7]]): «Ein Stern geht auf aus Jakob» ([[NUM.24.17]]). In Qumran wurde dieses Wort auf Gestalten der Endzeit bezogen, und der Anführer des Aufstands 132–135 n. Chr. wurde Bar Kochba, «Sternensohn», genannt. Für den Stern selbst werden natürliche Erklärungen vorgeschlagen, etwa die dreifache Begegnung von Jupiter und Saturn im Jahr 7 v. Chr., auf die schon Johannes Kepler hinwies.",
  "Keine astronomische Erklärung ist gesichert, und keine erklärt, dass der Stern vorausgeht und stehen bleibt ([[MAT.2.9]]). Zahl und Herkunft der Sterndeuter nennt der Text nicht (QUESTION-MAT-1002).",
  ["MAT.2.1-MAT.2.12", "NUM.23.7", "NUM.24.17", "ACT.13.6-ACT.13.8"],
  ["Herodot, Historien 1,101", "Damaskusschrift (CD) 7,18–21", "4Q175 (Testimonia)"],
  [("grc", "μάγος", "Magier, Sterndeuter"), ("grc", "ἀστήρ", "Stern"), ("heb", "כּוֹכָב", "Stern", "kôḵāḇ")],
  "Stärndüüter und Stärn",
  "Nach em Herodot sind d Magier en Stamm vo de Meder gsii, us dem Prieschter und Traumdüüter cho sind; spööter hät me so d Känner vo de Stärn und vo de Wiisheit us Persie und Babylonie gnännt, abwärtend au Zauberer ([[ACT.13.6-ACT.13.8]]). Z Babylonie isch d Stärnkund sit Jaarhunderte pflegt worde, und i de Antike hät me verbreitet glaubt, dass Stärn d Geburt vo Herrscher aazeiged. Z Israel hät me s Wort vom Bileam kännt, vo me Seher «us de Bärg vom Oschte» ([[NUM.23.7]]): «Es Stärn gaat uf us Jakob» ([[NUM.24.17]]). Z Qumran hät me das Wort uf Gstalte vo de Ändziit bezoge, und de Aafüerer vom Ufstand 132–135 n. Chr. isch Bar Kochba, «Stärnesohn», gnännt worde. Für de Stärn sälber wärded natürlichi Erklärige vorgschlage, öppe s drüüfach Zämetreffe vo Jupiter und Saturn im Jaar 7 v. Chr., uf das scho de Johannes Kepler hiigwise hät.",
  "Kei astronomischi Erklärig isch gsicheret, und keini erklärt, dass de Stärn voruusgaat und staa bliibt ([[MAT.2.9]]). Zaal und Härkunft vo de Stärndüüter nännt de Text nöd (QUESTION-MAT-1002).",
  ["Magier, Stärndüüter", "Stärn", "Stärn"]),
 ("BG-MAT-1006", U(2, 13, 15), "MAT.2.13-MAT.2.15", TEMPLE, "probable", "Ägypten als Zuflucht",
  "Ägypten war seit alter Zeit ein Zufluchtsort für Menschen aus Israel und Juda: Jerobeam floh vor Salomo dorthin ([[1KI.11.40]]), der Prophet Urija vor König Jojakim ([[JER.26.21]]), und nach dem Fall Jerusalems zog eine Gruppe mit Jeremia nach Ägypten ([[JER.43.4-JER.43.7]]). Zur Zeit Jesu lebten dort viele Juden, besonders in Alexandria; Philo schätzt ihre Zahl in Ägypten auf eine Million. In Leontopolis bestand bis 73 n. Chr. sogar ein jüdischer Tempel. Ägypten war seit 30 v. Chr. römische Provinz und stand nicht unter der Herrschaft des Herodes.",
  "Philos Zahl ist sicher übertrieben. Wo die Familie in Ägypten gelebt haben soll, sagt Matthäus nicht; spätere koptische Überlieferungen über die Stationen sind Legenden.",
  ["1KI.11.40", "JER.26.21", "JER.43.4-JER.43.7", "MAT.2.13-MAT.2.15"],
  ["Philo, Gegen Flaccus 43", "Josephus, Jüdische Altertümer 13,62–73"],
  [],
  "Ägypte als Zueflucht",
  "Ägypte isch sit alter Ziit en Zuefluchtsort gsii für Mänsche us Israel und Juda: De Jerobeam isch vor em Salomo dethii gflüchtet ([[1KI.11.40]]), de Prophet Urija vor em König Jojakim ([[JER.26.21]]), und nach em Fall vo Jerusalem isch e Gruppe mit em Jeremia uf Ägypte zoge ([[JER.43.4-JER.43.7]]). Zur Ziit vo Jesus händ dört vili Jude gläbt, bsunders z Alexandria; de Philo schätzt iri Zaal z Ägypte uf e Million. Z Leontopolis hät s bis 73 n. Chr. sogar en jüdische Tämpel ggää. Ägypte isch sit 30 v. Chr. e römischi Provinz gsii und isch nöd under de Herrschaft vom Herodes gstande.",
  "D Zaal vom Philo isch sicher übertribe. Wo d Familie z Ägypte söll gläbt haa, seit de Matthäus nöd; spööteri koptischi Überliferige über d Statione sind Legände.",
  []),
 ("BG-MAT-1007", U(2, 19, 23), "MAT.2.22-MAT.2.23", GAL, "probable", "Archelaus und Nazaret",
  "Nach dem Tod des Herodes teilte Augustus das Reich: Archelaus erhielt als Ethnarch Judäa, Samaria und Idumäa, Herodes Antipas als Tetrarch Galiläa und Peräa, Philippus die Gebiete im Nordosten. Archelaus begann mit Härte; Josephus berichtet von einem Blutbad im Tempel am ersten Passafest. Im Jahr 6 n. Chr. setzte ihn Augustus nach Klagen ab und verbannte ihn nach Vienne in Gallien; Judäa kam unter römische Statthalter. Nazaret war ein kleines Dorf im Hügelland Untergaliläas, wenige Kilometer von der Stadt Sepphoris. Es wird weder im Alten Testament noch bei Josephus oder in der Mischna erwähnt; die älteste ausserchristliche Nennung ist eine hebräische Inschrift der Priesterklassen aus Caesarea (3./4. Jh.).",
  "Die Grösse Nazarets im 1. Jahrhundert ist nur geschätzt (meist einige hundert Einwohner).",
  ["MAT.2.19-MAT.2.23", "JHN.1.46", "LUK.2.39"],
  ["Josephus, Jüdische Altertümer 17,213–218; 17,317–320; 17,342–344", "Inschrift der Priesterklassen aus Caesarea"],
  [("grc", "Ναζωραῖος", "Nazoräer; Mann aus Nazaret")],
  "Archelaus und Nazaret",
  "Nach em Tod vom Herodes hät de Augustus s Riich uufteilt: De Archelaus hät als Ethnarch Judäa, Samaria und Idumäa übercho, de Herodes Antipas als Tetrarch Galiläa und Peräa, de Philippus d Gebiet im Nordoschte. De Archelaus hät hert aagfange; de Josephus bricht vo me Bluetbad im Tämpel am erschte Passafäscht. Im Jaar 6 n. Chr. hät en de Augustus nach Chlage abgsetzt und uf Vienne in Gallie verbannt; Judäa isch under römischi Statthalter cho. Nazaret isch es chliises Dorf im Hügelland vo Undergaliläa gsii, es paar Kilometer vo de Stadt Sepphoris ewägg. Es wird weder im Alte Teschtament no bim Josephus oder i de Mischna erwäänt; di eltischt usserchristlich Nännig isch e hebräischi Inschrift vo de Prieschterklasse us Caesarea (3./4. Jh.).",
  "D Gröössi vo Nazaret im 1. Jaarhundert isch nu gschätzt (meischt es paar hundert Iiwooner).",
  ["Nazoräer; Maa us Nazaret"]),
 # Kapitel 3
 ("BG-MAT-1008", U(3, 1, 12), "MAT.3.1-MAT.3.6", TEMPLE, "probable", "Johannes der Täufer bei Josephus",
  "Josephus erwähnt Johannes, «genannt der Täufer», als guten Mann, der die Juden aufforderte, Tugend zu üben, Gerechtigkeit gegeneinander und Frömmigkeit gegenüber Gott, und zur Taufe zu kommen. Die Taufe sollte nach Josephus nicht Sünden tilgen, sondern den Leib reinigen, wenn die Seele schon durch Gerechtigkeit gereinigt war. Herodes Antipas fürchtete den Einfluss des Johannes auf die Menge und liess ihn in der Festung Machärus töten. Kleidung und Nahrung bei Matthäus passen zu einem Leben in der Wüste und erinnern an Elija ([[2KI.1.8]]); Heuschrecken waren erlaubte Speise ([[LEV.11.22]]).",
  "Josephus nennt andere Gründe für die Hinrichtung als die Evangelien ([[MAT.14.3-MAT.14.12]]); beide Darstellungen können sich ergänzen. Ob Josephus die Taufe richtig versteht oder seinen Lesern anpasst, ist umstritten.",
  ["MAT.3.1-MAT.3.6", "MAT.14.3-MAT.14.12", "2KI.1.8", "LEV.11.22"], ["Josephus, Jüdische Altertümer 18,116–119"],
  [("grc", "βαπτίζω", "eintauchen, taufen")],
  "De Johannes de Täufer bim Josephus",
  "De Josephus erwäänt de Johannes, «wo me de Täufer nännt», als guete Maa, wo d Jude ufgforderet hät, Tugend z üebe, Grächtigkeit gägenand und Frömmigkeit gägenüber Gott, und zur Taufi z cho. D Taufi hät nach em Josephus nöd Sünde sölle tilge, sondern de Liib reinige, wänn d Seel scho dur Grächtigkeit greiniget gsii isch. De Herodes Antipas hät de Iifluss vom Johannes uf d Lüüt gförchtet und en i de Feschtig Machärus loo töte. Chleidig und Ässe bim Matthäus passed zu me Läbe i de Wüeschti und erinnered a de Elija ([[2KI.1.8]]); Heuschrecke sind erlaubts Ässe gsii ([[LEV.11.22]]).",
  "De Josephus nännt anderi Gründ für d Hiirichtig als d Evangelie ([[MAT.14.3-MAT.14.12]]); beidi Darstellige chönd sich ergänze. Öb de Josephus d Taufi richtig verstaat oder sine Läser aapasst, isch umstritte.",
  ["iitauche, taufe"]),
 ("BG-MAT-1009", U(3, 1, 12), "MAT.3.3-MAT.3.11", TEMPLE, "probable", "Tauchbäder und Qumran",
  "Im Judäa und Galiläa des 1. Jahrhunderts gab es zahlreiche Tauchbäder (Mikwen) für die rituelle Reinigung. Man tauchte selbst unter, und zwar so oft, wie man unrein geworden war. Die Taufe des Johannes unterscheidet sich davon: Sie geschah einmal, durch ihn («von ihm», [[MAT.3.6]]), und war mit dem Bekenntnis der Sünden verbunden. Nicht weit vom unteren Jordan lebte am Toten Meer die Gemeinschaft von Qumran. Ihre Gemeinderegel begründet mit [[ISA.40.3]], dass die Gemeinschaft in die Wüste geht, um den Weg des Herrn durch das Studium der Tora zu bereiten, und sagt, dass Wasser nicht reinigt, wer sich nicht vom Bösen abwendet.",
  "Ob Johannes Verbindung zu Qumran hatte, ist Vermutung. Eine Taufe von Übertretenden zum Judentum (Proselytentaufe) ist erst in späteren Quellen sicher belegt.",
  ["MAT.3.1-MAT.3.11", "ISA.40.3"], ["Gemeinderegel (1QS) 3,4–9; 5,13–14; 8,12–16"],
  [("heb", "מִקְוֶה", "Tauchbad, Mikwe", "miqweh")],
  "Tauchbäder und Qumran",
  "Im Judäa und Galiläa vom 1. Jaarhundert hät s vili Tauchbäder (Mikwe) für di rituell Reinigung ggää. Me isch sälber undertoucht, und zwar so mängisch, wie me unrein worde isch. D Taufi vom Johannes isch anders gsii: Si isch eimal gscheh, dur ihn («vo ihm», [[MAT.3.6]]), und isch mit em Bekänntnis vo de Sünde verbunde gsii. Nöd wiit vom undere Jordan hät am Tote Meer d Gmeinschaft vo Qumran gläbt. Iri Gmeindsregle begründet mit [[ISA.40.3]], dass d Gmeinschaft i d Wüeschti gaat, zum de Wäg vom Herr dur s Studium vo de Tora parat z mache, und seit, dass Wasser dä nöd reiniget, wo sich nöd vom Böse abwändet.",
  "Öb de Johannes Verbindig zu Qumran ghaa hät, isch Vermuetig. E Taufi vo Mänsche, wo zum Judetum überträtted (Proselytetaufi), isch erscht i spöötere Quälle sicher belegt.",
  ["Tauchbad, Mikwe"]),
 ("BG-MAT-1010", U(3, 1, 12), "MAT.3.7", TEMPLE, "probable", "Pharisäer und Sadduzäer",
  "Josephus beschreibt drei jüdische «Schulen»: Pharisäer, Sadduzäer und Essener. Die Pharisäer galten als genaue Ausleger des Gesetzes, hielten an Überlieferungen der Väter fest, glaubten an die Auferstehung und waren im Volk angesehen. Die Sadduzäer gehörten zur priesterlichen Oberschicht, liessen nur das geschriebene Gesetz gelten und bestritten die Auferstehung ([[MAT.22.23]]; [[ACT.23.8]]). Politisch und in der Lehre standen die beiden Gruppen oft gegeneinander; Matthäus nennt sie mehrmals zusammen ([[MAT.3.7]]; [[MAT.16.1-MAT.16.12]]), als Vertreter der Führenden. Nach der Zerstörung des Tempels 70 n. Chr. verschwanden die Sadduzäer; das pharisäische Erbe lebte im rabbinischen Judentum weiter, mit dem sich die Gemeinde des Matthäus auseinandersetzte (BG-MAT-BOOK-0001; zu den Pharisäern auch BG-MRK-1007).",
  "Josephus beschreibt die Gruppen für griechisch-römische Leser als «Philosophenschulen»; wie viele Anhänger sie hatten und wie einflussreich sie in Galiläa waren, ist umstritten.",
  ["MAT.3.7", "MAT.16.1-MAT.16.12", "MAT.22.23", "ACT.23.8"],
  ["Josephus, Jüdische Altertümer 13,297–298; 18,11–17", "Josephus, Jüdischer Krieg 2,119–166"],
  [("heb", "פְּרוּשִׁים", "Pharisäer, wohl «die Abgesonderten»", "pᵉrûšîm")],
  "Pharisäer und Sadduzäer",
  "De Josephus beschriibt drüü jüdischi «Schuele»: Pharisäer, Sadduzäer und Essener. D Pharisäer händ als gnaui Uusleger vom Gsetz gulte, händ a Überliferige vo de Vätter feschtghalte, a d Uferstehig glaubt und sind im Volk aagsee gsii. D Sadduzäer händ zur prieschterliche Oberschicht ghört, händ nu s gschribe Gsetz loo gälte und d Uferstehig bestritte ([[MAT.22.23]]; [[ACT.23.8]]). Politisch und i de Lehr sind di beide Gruppe oft gägenand gstande; de Matthäus nännt si meereri Mal zäme ([[MAT.3.7]]; [[MAT.16.1-MAT.16.12]]), als Vertreter vo de Füerende. Nach de Zerstöörig vom Tämpel 70 n. Chr. sind d Sadduzäer verschwunde; s pharisäisch Erb hät im rabbinische Judetum wiitergläbt, mit dem sich d Gmeind vom Matthäus usenandgsetzt hät (BG-MAT-BOOK-0001; zu de Pharisäer au BG-MRK-1007).",
  "De Josephus beschriibt d Gruppe für griechisch-römischi Läser als «Philosopheschuele»; wie vili Aahänger si ghaa händ und wie iiflussriich si z Galiläa gsii sind, isch umstritte.",
  ["Pharisäer, wahrschiinli «di Abgsünderete»"]),
 # Kapitel 4
 ("BG-MAT-1011", U(4, 12, 17), "MAT.4.13-MAT.4.16", GAL, "probable", "Sebulon, Naftali und «Galiläa der Völker»",
  "Sebulon und Naftali waren die Stammesgebiete im Norden Israels. 733/732 v. Chr. eroberte der assyrische König Tiglat-Pileser III. das Gebiet und verschleppte Bewohner ([[2KI.15.29]]); in diese Lage spricht die Verheissung von [[ISA.9.1-ISA.9.2]]. «Galiläa der Völker» (hebräisch gᵉlîl haggôyim, «Kreis der Völker») bezeichnet ein Gebiet, das von nichtisraelitischen Nachbarn umgeben und durchmischt war. Unter den Hasmonäern kam Galiläa um 100 v. Chr. zum jüdischen Staat; zur Zeit Jesu war die Bevölkerung der Dörfer nach archäologischen Funden (Tauchbäder, Steingefässe, fehlende Schweineknochen) überwiegend jüdisch, umgeben von griechisch geprägten Städten. Kafarnaum lag am Nordufer des Sees im alten Gebiet Naftalis (zum Ort BG-MRK-1003).",
  "Ob Galiläa unter den Hasmonäern vor allem neu besiedelt oder seine Bevölkerung zum Judentum gebracht wurde, ist umstritten.",
  ["MAT.4.12-MAT.4.16", "2KI.15.29", "ISA.9.1-ISA.9.2"], ["Josephus, Jüdische Altertümer 13,318–319"],
  [("heb", "גְּלִיל הַגּוֹיִם", "Kreis, Bezirk der Völker", "gᵉlîl haggôyim")],
  "Sebulon, Naftali und «Galiläa vo de Völker»",
  "Sebulon und Naftali sind d Stammesgebiet im Norde vo Israel gsii. 733/732 v. Chr. hät de assyrisch König Tiglat-Pileser III. s Gebiet eroberet und Iiwooner verschleppt ([[2KI.15.29]]); i die Laag ine redt d Verheissig vo [[ISA.9.1-ISA.9.2]]. «Galiläa vo de Völker» (hebräisch gᵉlîl haggôyim, «Chreis vo de Völker») bezeichnet es Gebiet, wo vo nöd-israelitische Nachbere umgää und durmischt gsii isch. Under de Hasmonäer isch Galiläa um 100 v. Chr. zum jüdische Staat cho; zur Ziit vo Jesus isch d Bevölkerig vo de Dörfer nach archäologische Fünd (Tauchbäder, Steigfäss, fäälendi Söiknoche) vorwiegend jüdisch gsii, umgää vo griechisch prägte Stedt. Kafarnaum isch am Nordufer vom See im alte Gebiet vo Naftali gläge (zum Ort BG-MRK-1003).",
  "Öb Galiläa under de Hasmonäer vor allem nöi bsidlet oder sini Bevölkerig zum Judetum bracht worde isch, isch umstritte.",
  ["Chreis, Bezirk vo de Völker"]),
 ("BG-MAT-1012", U(4, 1, 11), "MAT.4.5-MAT.4.7", TEMPLE, "probable", "Der Tempel und seine «Zinne»",
  "Herodes liess den Tempel ab etwa 20 v. Chr. erneuern und den Tempelberg mit gewaltigen Stützmauern zu einer grossen Plattform erweitern. An der Südseite stand eine Säulenhalle, die über dem Kidrontal aufragte; Josephus schreibt, wer von ihrem Dach in die Tiefe blicke, dem werde schwindlig. Welche Stelle mit der «Zinne» (πτερύγιον, «Flügelchen») gemeint ist, weiss man nicht. Dasselbe Wort steht im Bericht des Hegesipp über den Tod des Jakobus, des Bruders Jesu, der von der «Zinne des Tempels» gestürzt worden sei. Der Teufel zitiert [[PSA.91.11-PSA.91.12]], einen Psalm vom Schutz Gottes für den, der ihm vertraut.",
  "Die Gleichsetzung der Zinne mit der Südostecke des Tempelbergs ist verbreitet, aber nicht gesichert.",
  ["MAT.4.5-MAT.4.7", "PSA.91.11-PSA.91.12"],
  ["Josephus, Jüdische Altertümer 15,380–425", "Hegesipp bei Eusebius, Kirchengeschichte 2,23"],
  [("grc", "πτερύγιον", "Flügelchen; vorspringender Gebäudeteil, Zinne")],
  "De Tämpel und sini «Zinne»",
  "De Herodes hät de Tämpel ab öppe 20 v. Chr. loo erneuere und de Tämpelbärg mit gwaltige Stützmuure zu ere groosse Plattform loo erwiitere. A de Südsiite isch e Süülehalle gstande, wo über s Kidrontal ufegragt hät; de Josephus schriibt, wär vo irem Dach abeluegi, dem wärdi s schwindlig. Weli Stell mit de «Zinne» (πτερύγιον, «Flügeli») gmeint isch, weiss me nöd. S gliich Wort staat im Bricht vom Hegesipp über de Tod vom Jakobus, em Brueder vo Jesus, wo vo de «Zinne vom Tämpel» abegstürzt worde seg. De Tüüfel zitiert [[PSA.91.11-PSA.91.12]], en Psalm vom Schutz vo Gott für dä, wo ihm vertrout.",
  "D Gliichsetzig vo de Zinne mit de Südoschtegge vom Tämpelbärg isch verbreitet, aber nöd gsicheret.",
  ["Flügeli; vorspringende Teil vo me Gebäude, Zinne"]),
 ("BG-MAT-1013", U(4, 23, 25), "MAT.4.24-MAT.4.25", GAL, "probable", "Syrien und die Dekapolis",
  "Syrien war seit 63 v. Chr. römische Provinz mit dem Statthalter in Antiochia; Judäa und Galiläa lagen in ihrem Einflussbereich. Die Dekapolis war eine Gruppe griechisch geprägter Städte, die meisten östlich des Jordan; Plinius der Ältere zählt sie auf, darunter Skythopolis, Gadara, Hippos und Gerasa (vgl. BG-MRK-1008). [[MAT.4.25]] nennt Galiläa, die Dekapolis, Jerusalem, Judäa und das Gebiet jenseits des Jordan, also im Wesentlichen das alte Land Israels und seine Nachbarschaft; Samarien und die phönizischen Küstenstädte fehlen. Dass sich die Kunde «in ganz Syrien» verbreitet ([[MAT.4.24]]), steht nur bei Matthäus.",
  "Ob «ganz Syrien» die Sicht der Leser des Matthäus spiegelt, die oft in Syrien vermutet werden (BG-MAT-BOOK-0001), ist eine Vermutung. Die Liste der Dekapolis-Städte schwankt in den antiken Quellen.",
  ["MAT.4.23-MAT.4.25", "MRK.3.7-MRK.3.8"], ["Plinius der Ältere, Naturgeschichte 5,74"],
  [],
  "Syrie und d Dekapolis",
  "Syrie isch sit 63 v. Chr. e römischi Provinz gsii mit em Statthalter z Antiochia; Judäa und Galiläa sind i irem Iiflussbereich gläge. D Dekapolis isch e Gruppe vo griechisch prägte Stedt gsii, di meischte öschtlich vom Jordan; de Plinius de Elter zellt si uf, drunder Skythopolis, Gadara, Hippos und Gerasa (vgl. BG-MRK-1008). [[MAT.4.25]] nännt Galiläa, d Dekapolis, Jerusalem, Judäa und s Gebiet änet em Jordan, also im Wäsentliche s alt Land vo Israel und sini Nachberschaft; Samarie und d phönizische Chüschtestedt fääled. Dass sich de Ruef «i ganz Syrie» verbreitet ([[MAT.4.24]]), staat nu bim Matthäus.",
  "Öb «ganz Syrie» d Sicht vo de Läser vom Matthäus spieglet, wo me oft z Syrie vermuetet (BG-MAT-BOOK-0001), isch e Vermuetig. D Lischte vo de Dekapolis-Stedt schwankt i de antike Quälle.",
  []),
 # Kapitel 5
 ("BG-MAT-1014", U(5, 1, 12), "MAT.5.3-MAT.5.12", TEMPLE, "probable", "Seligpreisungen als Redeform",
  "«Selig, wer …» (hebräisch ʾašrê, «wohl dem») ist eine vertraute Form der Psalmen und der Weisheit ([[PSA.1.1]]; [[PSA.32.1-PSA.32.2]]; [[PRO.3.13]]; [[SIR.14.20]]). Sie preist Menschen glücklich, die so leben, wie es Gott gefällt. In Qumran ist eine Reihe von Seligpreisungen erhalten, die den preisen, der an der Weisheit und der Tora festhält. In prophetischen und endzeitlichen Texten verheissen Seligpreisungen eine kommende Wende, etwa «Selig, wer ausharrt» ([[DAN.12.12]]). Die Seligpreisungen Jesu verbinden die Form der Weisheit mit der prophetischen Verheissung an Arme und Trauernde ([[ISA.61.1-ISA.61.3]]).",
  "Die Datierung des Qumran-Textes (4Q525) ist nicht genau bekannt; eine direkte Abhängigkeit besteht nicht.",
  ["PSA.1.1", "PSA.32.1-PSA.32.2", "PRO.3.13", "SIR.14.20", "DAN.12.12", "ISA.61.1-ISA.61.3"], ["4Q525 (Seligpreisungen aus Qumran)"],
  [("heb", "אַשְׁרֵי", "selig, wohl dem", "ʾašrê"), ("grc", "μακάριος", "selig, glücklich zu preisen")],
  "Säligpriisige als Redform",
  "«Sälig, wär …» (hebräisch ʾašrê, «wohl dem») isch e vertrauti Form vo de Psalme und vo de Wiisheit ([[PSA.1.1]]; [[PSA.32.1-PSA.32.2]]; [[PRO.3.13]]; [[SIR.14.20]]). Si priist Mänsche glücklich, wo so läbed, wie s Gott gfallt. Z Qumran isch e Reie vo Säligpriisige erhalte, wo dä priised, wo a de Wiisheit und de Tora feschthaltet. I prophetische und ändziitliche Text verheissed Säligpriisige e Wändi, wo chunnt, öppe «Sälig, wär uushaltet» ([[DAN.12.12]]). D Säligpriisige vo Jesus verbinded d Form vo de Wiisheit mit de prophetische Verheissig a Armi und Truurigi ([[ISA.61.1-ISA.61.3]]).",
  "D Datierig vom Qumran-Text (4Q525) isch nöd gnau bekannt; e diräkti Abhängigkeit git s nöd.",
  ["sälig, wohl dem", "sälig, glücklich z priise"]),
 ("BG-MAT-1015", U(5, 13, 16), "MAT.5.13-MAT.5.15", GAL, "possible", "Salz und Lampe",
  "Salz würzte und machte Speisen haltbar; es gehörte zu den Opfergaben, und man sprach vom «Salz des Bundes» ([[LEV.2.13]]; [[NUM.18.19]]). Reines Kochsalz verliert seinen Geschmack nicht. Salz aus der Gegend des Toten Meeres enthielt aber andere Mineralien; wurde das eigentliche Salz durch Feuchtigkeit ausgewaschen, blieb ein fader Rest, den man wegwarf. Andere halten das Bild bewusst für widersinnig: Salz, das nicht salzt, gibt es eigentlich nicht. Die Lampe war ein kleines tönernes Öllämpchen; in den meist einräumigen Häusern stellte man sie auf einen Ständer, damit sie den ganzen Raum erhellte. Der «Scheffel» war ein Getreidemass von knapp neun Litern.",
  "Die Erklärung mit dem ausgewaschenen Salz ist eine Vermutung; sie wird in Kommentaren oft angeführt, ist für die Zeit aber nicht ausdrücklich belegt.",
  ["MAT.5.13-MAT.5.15", "LEV.2.13", "NUM.18.19", "MRK.9.50", "LUK.14.34-LUK.14.35", "MRK.4.21"], [],
  [("grc", "ἅλας", "Salz"), ("grc", "λύχνος", "Öllampe")],
  "Salz und Lampe",
  "Salz hät gwürzt und Ässe haltbar gmacht; es hät zu de Opfergabe ghört, und me hät vom «Salz vom Bund» gredt ([[LEV.2.13]]; [[NUM.18.19]]). Reins Chochsalz verlüürt sin Gschmack nöd. Salz us de Gäged vom Tote Meer hät aber anderi Mineralie drin ghaa; isch s eigentlich Salz dur d Füechti uusgwäsche worde, isch en fade Räscht bliibe, wo me furtgrüert hät. Anderi haltet s Bild bewusst für widersinnig: Salz, wo nöd salzt, git s eigentli nöd. D Lampe isch es chliises Öllämpli us Ton gsii; i de meischt eiräumige Hüüser hät me si uf en Ständer gstellt, demit si de ganz Ruum hell gmacht hät. De «Schäffel» isch es Getreidemass vo chnapp nüün Liter gsii.",
  "D Erklärig mit em uusgwäschne Salz isch e Vermuetig; si wird i Kommentär oft aagfüert, isch für die Ziit aber nöd usdrücklich belegt.",
  ["Salz", "Öllampe"]),
 ("BG-MAT-1016", U(5, 27, 32), "MAT.5.31-MAT.5.32", TEMPLE, "high", "Scheidung in der jüdischen Diskussion",
  "Nach [[DEU.24.1]] durfte ein Mann seine Frau entlassen, wenn er «etwas Anstössiges» (ʿerwat dāḇār) an ihr fand, und musste ihr eine Scheidungsurkunde geben, die ihr eine neue Ehe erlaubte. Was als anstössig galt, war umstritten. Die Mischna überliefert: Die Schule Schammais erlaubte die Scheidung nur wegen sexueller Verfehlung, die Schule Hillels schon, wenn die Frau das Essen anbrennen liess, und Rabbi Akiba sogar, wenn der Mann eine schönere fand. Die Scheidung sprach in der Regel der Mann aus. Die Damaskusschrift aus Qumran kritisiert, wer zwei Frauen zu Lebzeiten nimmt. Die Ausnahme bei Matthäus ([[MAT.5.32]]; [[MAT.19.9]]) steht der Position Schammais nahe; Jesus geht mit der Verantwortung des Mannes für die entlassene Frau aber darüber hinaus.",
  "Die Mischna wurde um 200 n. Chr. zusammengestellt; dass die Positionen der Schulen ins 1. Jahrhundert zurückreichen, ist wahrscheinlich, aber nicht sicher. Was πορνεία bei Matthäus genau meint, ist offen (QUESTION-MAT-1003).",
  ["DEU.24.1-DEU.24.4", "MAT.5.31-MAT.5.32", "MAT.19.3-MAT.19.9", "MRK.10.2-MRK.10.12"],
  ["Mischna Gittin 9,10", "Damaskusschrift (CD) 4,20–5,2"],
  [("heb", "עֶרְוַת דָּבָר", "«Blösse einer Sache»: etwas Anstössiges", "ʿerwat dāḇār"), ("grc", "πορνεία", "Unzucht, sexuelle Verfehlung"), ("grc", "ἀποστάσιον", "Scheidebrief")],
  "Scheidig i de jüdische Diskussion",
  "Nach [[DEU.24.1]] hät en Maa sini Frau dörfe entlaa, wänn er «öppis Aastössigs» (ʿerwat dāḇār) a ire gfunde hät, und hät ere müese e Scheidigsurkund gää, wo ire e nöii Ee erlaubt hät. Was als aastössig gulte hät, isch umstritte gsii. D Mischna überliferet: D Schuel vom Schammai hät d Scheidig nu wäge sexueller Verfälig erlaubt, d Schuel vom Hillel scho, wänn d Frau s Ässe hät loo aabränne, und de Rabbi Akiba sogar, wänn de Maa e schöneri gfunde hät. D Scheidig hät i de Regle de Maa uusgsproche. D Damaskusschrift us Qumran kritisiert, wär zwei Fraue z Läbziite nimmt. D Uusnaam bim Matthäus ([[MAT.5.32]]; [[MAT.19.9]]) staat de Position vom Schammai nööch; de Jesus gaat mit de Verantwortig vom Maa für di entlaa Frau aber drüber use.",
  "D Mischna isch um 200 n. Chr. zämegstellt worde; dass d Positione vo de Schuele is 1. Jaarhundert zruggreiched, isch wahrschiinli, aber nöd sicher. Was πορνεία bim Matthäus gnau meint, isch offe (QUESTION-MAT-1003).",
  ["«Blööss vo ere Sach»: öppis Aastössigs", "Unzucht, sexuelli Verfälig", "Scheidigsbrief"]),
 ("BG-MAT-1017", U(5, 33, 37), "MAT.5.33-MAT.5.37", TEMPLE, "probable", "Schwören",
  "Eide gehörten zum Alltag und zum Recht. Um den Gottesnamen nicht zu missbrauchen, schwor man oft bei Ersatzworten: beim Himmel, bei der Erde, bei Jerusalem, beim Tempel oder beim eigenen Kopf (vgl. [[MAT.23.16-MAT.23.22]]). Die spätere rabbinische Überlieferung (Mischna, Traktate Schevuot und Nedarim) unterscheidet ausführlich, welche Formeln binden und welche nicht. Jesus Sirach warnt davor, sich ans Schwören zu gewöhnen ([[SIR.23.9-SIR.23.11]]). Von den Essenern berichtet Josephus, sie mieden das Schwören und hielten es für schlimmer als einen Meineid; bei der Aufnahme in die Gemeinschaft legten sie aber feierliche Eide ab. Der Jakobusbrief nimmt das Wort Jesu auf ([[JAS.5.12]]).",
  "Wie verbreitet die Ersatzformeln im 1. Jahrhundert waren, lässt sich nur aus späteren Quellen und aus [[MAT.23.16-MAT.23.22]] erschliessen.",
  ["MAT.5.33-MAT.5.37", "MAT.23.16-MAT.23.22", "SIR.23.9-SIR.23.11", "JAS.5.12", "LEV.19.12"],
  ["Josephus, Jüdischer Krieg 2,135; 2,139", "Mischna, Traktate Schevuot und Nedarim"],
  [("grc", "ὀμνύω", "schwören"), ("grc", "ἐπιορκέω", "falsch schwören; einen Eid brechen")],
  "Schwööre",
  "Eid händ zum Alltag und zum Rächt ghört. Zum de Gottesname nöd z missbruuche, hät me oft bi Ersatzwörter gschwore: bim Himel, bi de Ärde, bi Jerusalem, bim Tämpel oder bim eigete Chopf (vgl. [[MAT.23.16-MAT.23.22]]). Di spööter rabbinisch Überliferig (Mischna, Traktat Schevuot und Nedarim) underscheidet uusfüerlich, weli Formle binded und weli nöd. De Jesus Sirach warnt devor, sich as Schwööre z gwööne ([[SIR.23.9-SIR.23.11]]). Vo de Essener bricht de Josephus, si hebed s Schwööre gmide und für schlimmer ghalte als en Meineid; bi de Ufnaam i d Gmeinschaft händ si aber feierlichi Eid abgleit. De Jakobusbrief nimmt s Wort vo Jesus uf ([[JAS.5.12]]).",
  "Wie verbreitet d Ersatzformle im 1. Jaarhundert gsii sind, cha me nu us spöötere Quälle und us [[MAT.23.16-MAT.23.22]] erschlüüsse.",
  ["schwööre", "falsch schwööre; en Eid breche"]),
 ("BG-MAT-1018", U(5, 38, 42), "MAT.5.38-MAT.5.42", GAL, "probable", "Wange, Mantel und Meile",
  "Der Rechtssatz «Auge um Auge» ([[EXO.21.24]]) begrenzte die Vergeltung auf das Mass des Schadens. Die Mischna regelt Körperverletzungen mit Geldersatz für Schaden, Schmerz, Heilung, Arbeitsausfall und Beschämung; für einen Schlag mit dem Handrücken setzt sie eine höhere Busse fest als für einen gewöhnlichen Schlag, weil er mehr beschämt. Den Mantel durfte ein Gläubiger einem Armen nicht über Nacht behalten ([[EXO.22.26-EXO.22.27]]). Das Wort für «zwingen, mitzugehen» (ἀγγαρεύω) stammt aus dem persischen Botendienst, den Herodot beschreibt; im Römischen Reich durften Soldaten und Beamte Einheimische und ihre Tiere für Transporte heranziehen, wie Simon von Kyrene ([[MAT.27.32]]). Eine römische Meile mass etwa anderthalb Kilometer.",
  "Wie oft Zwangsdienste in Galiläa vorkamen, das nicht direkt unter römischer Verwaltung stand, ist unsicher.",
  ["EXO.21.24", "EXO.22.26-EXO.22.27", "MAT.5.38-MAT.5.42", "MAT.27.32"],
  ["Mischna Bava Qamma 8,1; 8,6", "Herodot, Historien 8,98"],
  [("grc", "ἀγγαρεύω", "zu einem Dienst zwingen, requirieren"), ("lat", "mille passus", "römische Meile: tausend Doppelschritte", "mille passus")],
  "Wange, Mantel und Meile",
  "De Rächtssatz «Aug um Aug» ([[EXO.21.24]]) hät d Vergältig uf s Mass vom Schade begränzt. D Mischna reglet Chörperverletzige mit Gälders für Schade, Schmärz, Heilig, Arbetsuusfall und Beschämig; für en Schlag mit em Handrugge setzt si e högeri Buess fescht als für en gwöönliche Schlag, wil er meh beschämt. De Mantel hät en Gläubiger eme Arme nöd über d Nacht dörfe bhalte ([[EXO.22.26-EXO.22.27]]). S Wort für «zwinge, mitzgaa» (ἀγγαρεύω) stammt us em persische Botedienscht, wo de Herodot beschriibt; im Römische Riich händ Soldate und Beamti Iiheimischi und iri Tier für Transport dörfe heranää, wie de Simon vo Kyrene ([[MAT.27.32]]). E römischi Meile isch öppe anderthalb Kilometer lang gsii.",
  "Wie oft Zwangsdienscht z Galiläa vorcho sind, wo nöd diräkt under römischer Verwaltig gstande isch, isch unsicher.",
  ["zu me Dienscht zwinge, requiriere", "römischi Meile: tuusig Doppelschritt"]),
 ("BG-MAT-1019", U(5, 43, 48), "MAT.5.43-MAT.5.47", TEMPLE, "probable", "Nächstenliebe und Feindeshass",
  "Das Gebot «Du sollst deinen Nächsten lieben» ([[LEV.19.18]]) meint im Zusammenhang den Volksgenossen; [[LEV.19.34]] dehnt es auf den Fremden aus, der im Land lebt. Ein Gebot, den Feind zu hassen, gibt es im Alten Testament nicht; die Weisung kennt im Gegenteil Hilfe für den Feind ([[EXO.23.4-EXO.23.5]]; [[PRO.25.21]]). Einzelne Psalmen sprechen aber von Hass gegen die Feinde Gottes ([[PSA.139.21-PSA.139.22]]), und die Gemeinderegel von Qumran verpflichtet, «alle Söhne des Lichts zu lieben» und «alle Söhne der Finsternis zu hassen». Grüssen ([[MAT.5.47]]) hiess, jemandem den Frieden zu wünschen und ihn als zugehörig anzuerkennen.",
  "Ob Jesu Wort auf Anschauungen wie in Qumran antwortet oder eine verbreitete Folgerung aus der Nächstenliebe aufnimmt, ist offen.",
  ["LEV.19.18", "LEV.19.34", "EXO.23.4-EXO.23.5", "PRO.25.21", "PSA.139.21-PSA.139.22", "MAT.5.43-MAT.5.47"],
  ["Gemeinderegel (1QS) 1,9–10"],
  [("heb", "רֵעַ", "Nächster, Mitmensch, Gefährte", "rēaʿ")],
  "Nächschteliebi und Findeshass",
  "S Gebot «Du söllsch din Nächschte liebe» ([[LEV.19.18]]) meint im Zämehang de Volksgnoss; [[LEV.19.34]] dehnt s uf de Frömd uus, wo im Land läbt. Es Gebot, de Find z hasse, git s im Alte Teschtament nöd; d Wiisig kännt im Gägeteil Hilf für de Find ([[EXO.23.4-EXO.23.5]]; [[PRO.25.21]]). Einzelni Psalme reded aber vo Hass gäge d Find vo Gott ([[PSA.139.21-PSA.139.22]]), und d Gmeindsregle vo Qumran verpflichtet, «alli Söön vom Liecht z liebe» und «alli Söön vo de Fiischteri z hasse». Grüesse ([[MAT.5.47]]) hät gheisse, öpperem de Fride wünsche und en als zuegehörig aaerchänne.",
  "Öb s Wort vo Jesus uf Aasichte wie z Qumran antwortet oder e verbreiteti Folgerig us de Nächschteliebi ufnimmt, isch offe.",
  ["Nächschte, Mitmänsch, Gfährte"]),
 # Kapitel 6
 ("BG-MAT-1020", U(6, 1, 4), "MAT.6.1-MAT.6.4", TEMPLE, "probable", "Almosen",
  "Die Sorge für die Armen gebietet schon die Tora ([[DEU.15.7-DEU.15.11]]; [[LEV.19.9-LEV.19.10]]). In der Zeit des Zweiten Tempels wurde das Almosen zu einer Hauptform der Frömmigkeit und eng mit der Gerechtigkeit verbunden; das hebräische ṣᵉdāqāh «Gerechtigkeit» bedeutet später auch «Almosen». Das Buch Tobit sagt: «Gut ist Gebet mit Fasten und Almosen … Almosen rettet vom Tod» ([[TOB.12.8-TOB.12.9]]; vgl. [[SIR.3.30]]). Die Mischna kennt eine tägliche Armenschüssel und eine wöchentliche Armenkasse der Gemeinde. Sie erwähnt auch eine «Kammer der Verschwiegenen» im Tempel, in die Fromme heimlich gaben und aus der Arme aus guten Familien heimlich nahmen. Ob Spender öffentlich mit Posaunen geehrt wurden, ist nicht belegt (siehe die Übersetzungsentscheidung zu [[MAT.6.2]]).",
  "Die Mischna ist später als Matthäus; die Einrichtungen können älter sein, sind für das 1. Jahrhundert aber nicht einzeln belegt.",
  ["DEU.15.7-DEU.15.11", "LEV.19.9-LEV.19.10", "TOB.12.8-TOB.12.9", "SIR.3.30", "MAT.6.1-MAT.6.4"],
  ["Mischna Pea 8,7", "Mischna Scheqalim 5,6; 6,5"],
  [("heb", "צְדָקָה", "Gerechtigkeit; später auch Almosen", "ṣᵉdāqāh"), ("grc", "ἐλεημοσύνη", "Barmherzigkeit; Almosen")],
  "Almose",
  "D Sorg für d Arme verlangt scho d Tora ([[DEU.15.7-DEU.15.11]]; [[LEV.19.9-LEV.19.10]]). I de Ziit vom Zweite Tämpel isch s Almose zu ere Hauptform vo de Frömmigkeit worde und äng mit de Grächtigkeit verbunde gsii; s hebräisch ṣᵉdāqāh «Grächtigkeit» bedüütet spööter au «Almose». S Buech Tobit seit: «Guet isch s Gebätt mit Faschte und Almose … Almose rettet vom Tod» ([[TOB.12.8-TOB.12.9]]; vgl. [[SIR.3.30]]). D Mischna kännt e täglichi Armeschüssle und e wöchentlichi Armechasse vo de Gmeind. Si erwäänt au e «Chammere vo de Verschwigene» im Tämpel, wo Frommi heimlich ggää händ und Armi us guete Familie heimlich gnoo händ. Öb Spänder öffentlich mit Posuune gehrt worde sind, isch nöd belegt (lueg d Übersetzigsentscheidig zu [[MAT.6.2]]).",
  "D Mischna isch spööter als de Matthäus; d Iirichtige chönd elter sii, sind fürs 1. Jaarhundert aber nöd einzeln belegt.",
  ["Grächtigkeit; spööter au Almose", "Barmhärzigkeit; Almose"]),
 ("BG-MAT-1021", U(6, 16, 18), "MAT.6.16-MAT.6.18", TEMPLE, "probable", "Fasten",
  "Die Tora gebietet ein Fasten am Versöhnungstag («ihr sollt euch demütigen», [[LEV.16.29]]; [[LEV.16.31]]); nach dem Exil kamen Fasttage zur Erinnerung an die Zerstörung Jerusalems hinzu ([[ZEC.8.19]]). Dazu fasteten Einzelne in Trauer, Busse oder dringender Bitte. Der Pharisäer im Gleichnis fastet zweimal in der Woche ([[LUK.18.12]]); die Didache weist Christen an, nicht wie «die Heuchler» am zweiten und fünften Wochentag zu fasten, sondern am vierten und am Rüsttag. Zum Fasten gehörte, sich nicht zu waschen und nicht zu salben; die Mischna zählt das zu den Verboten des Versöhnungstags, dazu oft Sack und Asche. Jesus setzt voraus, dass seine Jünger fasten, und verlangt nur, dass man es ihnen nicht ansieht ([[MAT.6.17-MAT.6.18]]; vgl. [[MAT.9.14-MAT.9.15]]).",
  "Dass Pharisäer am Montag und Donnerstag fasteten, folgt aus der Didache und späteren rabbinischen Quellen; für die Zeit Jesu ist es nicht sicher.",
  ["LEV.16.29", "LEV.16.31", "ZEC.8.19", "LUK.18.12", "MAT.6.16-MAT.6.18", "MAT.9.14-MAT.9.15"],
  ["Didache 8,1", "Mischna Joma 8,1"],
  [("grc", "νηστεύω", "fasten")],
  "Faschte",
  "D Tora verlangt es Faschte am Versöönigstag («ir söled eu demüetige», [[LEV.16.29]]; [[LEV.16.31]]); nach em Exil sind Faschttäg dezuecho zur Erinnerig a d Zerstöörig vo Jerusalem ([[ZEC.8.19]]). Dezue händ Einzelni gfaschtet i de Truur, als Buess oder bi ere dringende Bitt. De Pharisäer im Gliichnis faschtet zweimal i de Wuche ([[LUK.18.12]]); d Didache wiist d Christe aa, nöd wie «d Hüüchler» am zweite und föifte Wuchetag z faschte, sondern am vierte und am Rüschttag. Zum Faschte hät ghört, sich nöd z wäsche und nöd z salbe; d Mischna zellt das zu de Verbot vom Versöönigstag, dezue oft Sack und Äsche. De Jesus setzt voruus, dass sini Jünger faschted, und verlangt nu, dass me s ine nöd aagseet ([[MAT.6.17-MAT.6.18]]; vgl. [[MAT.9.14-MAT.9.15]]).",
  "Dass Pharisäer am Mäntig und am Dunschtig gfaschtet händ, folgt us de Didache und spöötere rabbinische Quälle; für d Ziit vo Jesus isch es nöd sicher.",
  ["faschte"]),
 ("BG-MAT-1022", U(6, 19, 24), "MAT.6.22-MAT.6.23", READERS, "possible", "Das Auge als Lampe",
  "Viele antike Denker meinten, dass das Auge selbst Licht aussendet und damit die Dinge erfasst; Platon beschreibt ein «Feuer» im Auge, das nach aussen strömt. Andere, etwa die Atomisten, dachten umgekehrt an Bilder, die ins Auge eindringen. In der Bibel ist das «böse Auge» (ʿayin rāʿāh) eine Wendung für Missgunst und Geiz ([[DEU.15.9]]; [[PRO.23.6]]; [[PRO.28.22]]), das «gute Auge» für Grosszügigkeit ([[PRO.22.9]]); so auch [[MAT.20.15]]. Verbreitet war zudem der Glaube an den schädlichen «bösen Blick», gegen den man Amulette trug.",
  "Welche Vorstellung vom Sehen Matthäus und seine Leser hatten, ist nicht bekannt; das Bildwort lässt sich mit beiden Theorien verstehen.",
  ["MAT.6.22-MAT.6.23", "DEU.15.9", "PRO.23.6", "PRO.28.22", "PRO.22.9", "MAT.20.15"], ["Platon, Timaios 45b–46a"],
  [("heb", "עַיִן רָעָה", "«böses Auge»: Missgunst, Geiz", "ʿayin rāʿāh"), ("grc", "ἁπλοῦς", "einfach, ungeteilt; vom Auge: gesund, klar")],
  "S Aug als Lampe",
  "Vili antiki Dänker händ gmeint, dass s Aug sälber Liecht uusschickt und demit d Sache erfasst; de Platon beschriibt es «Füür» im Aug, wo nach usse strömt. Anderi, öppe d Atomischte, händ umgchehrt a Bilder tänkt, wo is Aug iidringed. I de Bible isch s «bös Aug» (ʿayin rāʿāh) e Wändig für Missgunscht und Giiz ([[DEU.15.9]]; [[PRO.23.6]]; [[PRO.28.22]]), s «guet Aug» für Grosszügigkeit ([[PRO.22.9]]); so au [[MAT.20.15]]. Verbreitet isch zuedem de Glaube a de schädlich «bös Blick» gsii, gäge dä me Amulett treit hät.",
  "Weli Vorstellig vom Gseh de Matthäus und sini Läser ghaa händ, isch nöd bekannt; s Bildwort cha me mit beidne Theorie verstaa.",
  ["«bööses Aug»: Missgunscht, Giiz", "eifach, ungteilt; vom Aug: gsund, klar"]),
 # Kapitel 7
 ("BG-MAT-1023", U(7, 7, 12), "MAT.7.12", READERS, "high", "Die Goldene Regel",
  "Die Regel, andere so zu behandeln, wie man selbst behandelt werden möchte, ist in vielen Kulturen bekannt, meist in verneinter Form. Im Buch Tobit heisst es: «Was du hassest, das tu niemandem» ([[TOB.4.15]]). Der Babylonische Talmud erzählt, Hillel habe einem Nichtjuden, der die ganze Tora auf einem Bein stehend lernen wollte, gesagt: «Was dir verhasst ist, das tu deinem Nächsten nicht. Das ist die ganze Tora; das andere ist Auslegung.» Ähnlich lauten der Aristeasbrief, der griechische Redner Isokrates und Konfuzius. Jesus formuliert die Regel positiv, wie auch [[LUK.6.31]], und nennt sie «das Gesetz und die Propheten» ([[MAT.7.12]]; vgl. [[MAT.22.40]]).",
  "Ob die positive Form inhaltlich mehr verlangt als die verneinte, ist umstritten; auch positive Fassungen sind ausserhalb der Bibel belegt. Die Hillel-Erzählung ist erst im Talmud überliefert.",
  ["MAT.7.12", "LUK.6.31", "TOB.4.15", "MAT.22.40"],
  ["Babylonischer Talmud, Schabbat 31a", "Aristeasbrief 207", "Isokrates, Nikokles 61", "Konfuzius, Gespräche 15,24"],
  [],
  "Di Goldig Regle",
  "D Regle, anderi so z behandle, wie me sälber wett behandlet wärde, isch i vile Kulture bekannt, meischt i verneinter Form. Im Buech Tobit heissts: «Was du hassisch, das tue niemertem» ([[TOB.4.15]]). De Babylonisch Talmud verzellt, de Hillel heg eme Nöd-Jud, wo di ganz Tora uf eim Bei staand hät wele lerne, gseit: «Was dir verhasst isch, das tue dim Nächschte nöd. Das isch di ganz Tora; s ander isch Uuslegig.» Ähnlich tönt s im Aristeasbrief, bim griechische Redner Isokrates und bim Konfuzius. De Jesus formuliert d Regle positiv, wie au [[LUK.6.31]], und nännt si «s Gsetz und d Prophete» ([[MAT.7.12]]; vgl. [[MAT.22.40]]).",
  "Öb di positiv Form inhaltlich meh verlangt als di verneint, isch umstritte; au positivi Fassige sind usserhalb vo de Bible belegt. D Hillel-Gschicht isch erscht im Talmud überliferet.",
  []),
 ("BG-MAT-1024", U(7, 15, 23), "MAT.7.15-MAT.7.23", READERS, "probable", "Falsche Propheten in den frühen Gemeinden",
  "In den frühen christlichen Gemeinden traten Propheten auf, die von Ort zu Ort zogen. Die Didache, eine Gemeindeordnung aus der Zeit um 100, gibt Merkmale an: Nicht jeder, der im Geist redet, ist ein Prophet, sondern nur, wer die Lebensweise des Herrn hat; wer länger als zwei Tage bleibt oder Geld für sich verlangt, ist ein falscher Prophet. Schon die Tora nennt Prüfsteine: Ein Prophet, der zu anderen Göttern führt, ist abzuweisen, auch wenn sein Zeichen eintrifft ([[DEU.13.1-DEU.13.5]]; vgl. [[DEU.18.21-DEU.18.22]]). Matthäus warnt auch in der Endzeitrede vor falschen Propheten, die Zeichen tun ([[MAT.24.11]]; [[MAT.24.24]]).",
  "Wen Matthäus mit den falschen Propheten meint, sagt er nicht; Vermutungen reichen von gesetzesfreien Wanderpropheten bis zu Gegnern in der eigenen Gemeinde.",
  ["MAT.7.15-MAT.7.23", "MAT.24.11", "MAT.24.24", "DEU.13.1-DEU.13.5", "DEU.18.21-DEU.18.22"], ["Didache 11"],
  [("grc", "ψευδοπροφήτης", "falscher Prophet")],
  "Falschi Prophete i de früene Gmeinde",
  "I de früene christliche Gmeinde sind Prophete uufträtte, wo vo Ort zu Ort zoge sind. D Didache, e Gmeindsornig us de Ziit um 100, git Merkmal aa: Nöd jede, wo im Geischt redt, isch en Prophet, sondern nu dä, wo d Läbeswiis vom Herr hät; wär länger als zwei Täg bliibt oder Gält für sich verlangt, isch en falsche Prophet. Scho d Tora nännt Prüefstei: En Prophet, wo zu andere Götter füert, söll me abwiise, au wänn sis Zeiche iitrifft ([[DEU.13.1-DEU.13.5]]; vgl. [[DEU.18.21-DEU.18.22]]). De Matthäus warnt au i de Ändziitred vor falsche Prophete, wo Zeiche tüend ([[MAT.24.11]]; [[MAT.24.24]]).",
  "Wän de Matthäus mit de falsche Prophete meint, seit er nöd; d Vermuetige reiched vo Wanderprophete, wo s Gsetz nöd halted, bis zu Gägner i de eigete Gmeind.",
  ["falsche Prophet"]),
 ("BG-MAT-1025", U(7, 24, 27), "MAT.7.24-MAT.7.27", GAL, "possible", "Bauen auf Fels und Sand",
  "In Galiläa baute man Häuser meist aus Feldsteinen, in der Gegend des Sees aus Basalt, mit einem Dach aus Balken, Zweigen und gestampftem Lehm. Wo es möglich war, setzte man die Mauern auf den gewachsenen Fels. In der Regenzeit von etwa November bis März können heftige Regen fallen; trockene Bachtäler (Wadis) werden dann in kurzer Zeit zu reissenden Fluten. Wer im trockenen Sommer auf ebenem Sand baut, spart Arbeit und erlebt im Winter den Schaden. Lukas erzählt das Gleichnis vom Bauherrn, der «tief grub und das Fundament auf den Felsen legte» ([[LUK.6.48]]). Das Bild vom Unwetter, das den Gottlosen hinwegrafft, während der Gerechte besteht, kennt auch die Weisheit ([[PRO.10.25]]; [[PRO.12.7]]).",
  "Die Beschreibung der Bauweise ist allgemein; das Gleichnis setzt keinen bestimmten Ort voraus.",
  ["MAT.7.24-MAT.7.27", "LUK.6.47-LUK.6.49", "PRO.10.25", "PRO.12.7"], [],
  [],
  "Baue uf Fels und Sand",
  "Z Galiläa hät me Hüüser meischt us Fäldstei baut, i de Gäged vom See us Basalt, mit eme Dach us Balke, Ascht und gstampftem Leem. Wo s gange isch, hät me d Muure uf de gwachse Fels gstellt. I de Rägeziit vo öppe Novämber bis März chönd heftigi Räge abecho; trochni Bachtäler (Wadis) wärded dänn in churzer Ziit zu riissende Flute. Wär im trochne Summer uf ebnem Sand buut, spart Arbet und erläbt im Winter de Schade. De Lukas verzellt s Gliichnis vom Bauherr, wo «tüüf grabe und s Fundament uf de Fels gleit hät» ([[LUK.6.48]]). S Bild vom Unwätter, wo de Gottlos wägrafft, wäred de Grächt bestaat, kännt au d Wiisheit ([[PRO.10.25]]; [[PRO.12.7]]).",
  "D Beschriibig vo de Bauwiis isch allgemein; s Gliichnis setzt kein bestimmte Ort voruus.",
  []),
 ("BG-MAT-1026", U(7, 28, 29), "MAT.7.28-MAT.7.29", TEMPLE, "probable", "Schriftgelehrte und Vollmacht",
  "Schriftgelehrte waren Kundige der Schrift und des Rechts; Jesus Sirach zeichnet das Bild des Gelehrten, der das Gesetz des Höchsten und die Weisheit der Alten erforscht ([[SIR.38.24-SIR.39.11]]). Lehrer begründeten ihre Auslegung mit der Schrift und mit der Überlieferung früherer Lehrer; die Mischna beginnt den Traktat Avot mit einer Kette der Überlieferung von Mose bis zu den Weisen, und in rabbinischen Texten heisst es oft «Rabbi X sagt im Namen von Rabbi Y». Ein Lehrer, der wie Jesus «Ich aber sage euch» sagt, ohne sich auf Vorgänger zu berufen, fiel auf. Matthäus kennt auch Schriftgelehrte, die zu Jüngern des Himmelreichs geworden sind ([[MAT.13.52]]; [[MAT.23.34]]).",
  "Die rabbinischen Zitierweisen sind erst ab etwa 200 n. Chr. schriftlich belegt; für die Zeit Jesu sind sie erschlossen.",
  ["MAT.7.28-MAT.7.29", "SIR.38.24-SIR.39.11", "MAT.13.52", "MAT.23.34", "MRK.1.22"], ["Mischna Avot 1,1"],
  [("grc", "γραμματεύς", "Schreiber, Schriftgelehrter"), ("grc", "ἐξουσία", "Vollmacht, rechtmässige Befugnis")],
  "Schriftgelehrti und Vollmacht",
  "Schriftgelehrti sind Känner vo de Schrift und vom Rächt gsii; de Jesus Sirach zeichnet s Bild vom Gelehrte, wo s Gsetz vom Höchschte und d Wiisheit vo de Alte erforscht ([[SIR.38.24-SIR.39.11]]). Lehrer händ iri Uuslegig mit de Schrift und mit de Überliferig vo frünere Lehrer begründet; d Mischna fangt de Traktat Avot mit ere Chette vo de Überliferig vom Mose bis zu de Wiise aa, und i rabbinische Text heissts oft «Rabbi X seit im Name vom Rabbi Y». En Lehrer, wo wie de Jesus «Ich aber säg eu» seit, ohni sich uf Vorgänger z berüefe, isch ufgfalle. De Matthäus kännt au Schriftgelehrti, wo zu Jünger vom Himelriich worde sind ([[MAT.13.52]]; [[MAT.23.34]]).",
  "D rabbinische Zitierwiise sind erscht ab öppe 200 n. Chr. schriftlich belegt; für d Ziit vo Jesus sind si erschlosse.",
  ["Schriiber, Schriftgelehrte", "Vollmacht, rächtmääsigi Befuegnis"]),
]

# Kapitel-Zusammenfassungen (SUM-CH-MAT-006 besteht aus vaterunser.py und wird hier nicht geschrieben)
SUMMARIES = [
 ("SUM-CH-MAT-001",
  "Matthäus beginnt mit dem Stammbaum Jesu Christi, des Sohnes Davids und Abrahams: dreimal vierzehn Generationen von Abraham über David und die Wegführung nach Babylon bis zu Josef, dem Mann Marias, von der Jesus geboren wurde. Maria ist mit Josef verlobt und wird schwanger vom heiligen Geist. Josef will sich heimlich von ihr trennen, doch ein Engel des Herrn sagt ihm im Traum, er solle sie zu sich nehmen und dem Sohn den Namen Jesus geben. So erfüllt sich das Prophetenwort vom Immanuel, «Gott mit uns». Josef nimmt Maria zu sich, schläft nicht mit ihr, bis sie den Sohn geboren hat, und gibt ihm den Namen Jesus.",
  "De Matthäus fangt mit em Stammbaum vo Jesus Christus aa, em Sohn vom David und vom Abraham: drüümal vierzää Generatione vom Abraham über de David und d Wägfüerig uf Babylon bis zum Josef, em Maa vo de Maria, vo dere de Jesus gebore worde isch. D Maria isch mit em Josef verlobt und wird schwanger vom heilige Geischt. De Josef wott sich heimlich vo ire trenne, aber en Ängel vom Herr seit ihm im Traum, er söll si zu sich neh und em Sohn de Name Jesus gää. So erfüllt sich s Prophetewort vom Immanuel, «Gott mit üs». De Josef nimmt d Maria zu sich, schlaft nöd mit ire, bis si de Sohn übercho hät, und git ihm de Name Jesus."),
 ("SUM-CH-MAT-002",
  "Als Jesus zur Zeit des Königs Herodes in Betlehem geboren ist, kommen Sterndeuter aus dem Osten nach Jerusalem und suchen den neugeborenen König der Juden. Herodes erschrickt, erfährt von den Hohepriestern und Schriftgelehrten, dass der Christus in Betlehem geboren werden soll, und schickt die Sterndeuter mit dem Auftrag dorthin, ihm das Kind zu melden. Der Stern führt sie zum Haus; sie werfen sich vor dem Kind nieder, bringen Gold, Weihrauch und Myrrhe und kehren nach einer Weisung im Traum auf einem anderen Weg heim. Ein Engel schickt Josef mit dem Kind und seiner Mutter nach Ägypten, und Herodes lässt in Betlehem und Umgebung alle Knaben bis zu zwei Jahren töten. Nach dem Tod des Herodes kehrt Josef zurück, meidet Judäa unter Archelaus und lässt sich in Nazaret in Galiläa nieder. Betlehem, Ägypten, Rama und Nazaret sind jeweils mit einem Prophetenwort verbunden.",
  "Wo de Jesus zur Ziit vom König Herodes z Betlehem gebore isch, chömed Stärndüüter us em Oschte uf Jerusalem und sueched de nöigeborne König vo de Jude. De Herodes verschrickt, erfahrt vo de Hoheprieschter und Schriftgelehrte, dass de Christus z Betlehem söll gebore wärde, und schickt d Stärndüüter mit em Uftrag dethii, ihm s Chind z mälde. De Stärn füert si zum Huus; si wärfed sich vor em Chind nider, bringed Gold, Wiirauch und Myrrhe und gönd nach ere Wiisig im Traum uf eme andere Wäg hei. En Ängel schickt de Josef mit em Chind und sinere Mueter uf Ägypte, und de Herodes laat z Betlehem und i de Umgäbig alli Buebe bis zu zwei Jaar töte. Nach em Tod vom Herodes chunnt de Josef zrugg, meidet Judäa under em Archelaus und laat sich z Nazaret z Galiläa nider. Betlehem, Ägypte, Rama und Nazaret sind jedes mit eme Prophetewort verbunde."),
 ("SUM-CH-MAT-003",
  "Johannes der Täufer tritt in der Wüste Judäas auf und ruft: «Kehrt um, denn das Reich der Himmel ist nahe gekommen!» Der Text bezieht auf ihn das Jesajawort von der Stimme in der Wüste. Viele lassen sich im Jordan von ihm taufen und bekennen ihre Sünden. Den Pharisäern und Sadduzäern kündigt er das Gericht an und fordert Frucht der Umkehr; nach ihm komme ein Stärkerer, der mit heiligem Geist und Feuer taufen werde. Jesus kommt aus Galiläa, um sich taufen zu lassen. Johannes will ihn abhalten, doch Jesus sagt, so gehöre es sich, alle Gerechtigkeit zu erfüllen. Nach der Taufe sieht Jesus den Geist Gottes wie eine Taube auf sich kommen, und eine Stimme aus den Himmeln sagt: «Dieser ist mein geliebter Sohn, an dem ich Gefallen gefunden habe.»",
  "De Johannes de Täufer tritt i de Wüeschti vo Judäa uf und rüeft: «Chehred um, dänn s Riich vo de Himel isch nöch choo!» De Text bezieht s Jesajawort vo de Stimm i de Wüeschti uf ihn. Vili lönd sich im Jordan vo ihm taufe und bekänned iri Sünde. De Pharisäer und Sadduzäer chündet er s Gricht aa und forderet Frucht, wo zur Umkehr passt; nach ihm chöm en Stercherer, wo mit heilige Geischt und Füür wärd taufe. De Jesus chunnt vo Galiläa, zum sich la taufe. De Johannes wott en abhalte, aber de Jesus seit, so ghör es sich, alli Grächtigkeit z erfülle. Nach de Taufi gseet de Jesus de Geischt vo Gott wie e Tuube uf sich choo, und e Stimm us de Himel seit: «Dä isch min liebe Sohn, a däm han ich Gfalle gfunde.»"),
 ("SUM-CH-MAT-004",
  "Der Geist führt Jesus in die Wüste, damit er vom Teufel versucht wird. Nach vierzig Tagen und Nächten Fasten fordert ihn der Versucher auf, Steine zu Brot zu machen, sich von der Zinne des Tempels hinabzuwerfen und ihn für alle Reiche der Welt anzubeten. Jesus antwortet jedes Mal mit einem Schriftwort; der Teufel verlässt ihn, und Engel dienen ihm. Als Johannes ausgeliefert ist, zieht sich Jesus nach Galiläa zurück und lässt sich in Kafarnaum nieder; so erfüllt sich Jesajas Wort vom Licht für Galiläa der Völker. Jesus verkündigt: «Kehrt um, denn das Reich der Himmel ist nahe gekommen!» Am See ruft er Simon Petrus und Andreas, Jakobus und Johannes, und sie folgen ihm. Er zieht durch Galiläa, lehrt, verkündigt das Evangelium vom Reich und heilt; Menschenmengen aus Galiläa, der Dekapolis, Jerusalem, Judäa und von jenseits des Jordan folgen ihm.",
  "De Geischt füert de Jesus i d Wüeschti, demit er vom Tüüfel versuecht wird. Nach vierzg Täg und Nächt Faschte forderet en de Versuecher uf, Stei zu Broot z mache, sich vo de Zinne vom Tämpel abezrüere und ihn für alli Riich vo de Wält aazbätte. De Jesus antwortet jedes Mal mit eme Schriftwort; de Tüüfel laat vo ihm ab, und Ängel diened ihm. Wo de Johannes usgliferet isch, ziet sich de Jesus uf Galiläa zrugg und laat sich z Kafarnaum nider; so erfüllt sich s Wort vom Jesaja vom Liecht für Galiläa vo de Völker. De Jesus verchündet: «Chehred um, dänn s Riich vo de Himel isch nöch choo!» Am See rüeft er de Simon Petrus und de Andreas, de Jakobus und de Johannes, und si gönd ihm nache. Er ziet dur Galiläa, leert, verchündet s Evangelium vom Riich und heilt; Lüüt us Galiläa, de Dekapolis, Jerusalem, Judäa und vo änet em Jordan gönd ihm nache."),
 ("SUM-CH-MAT-005",
  "Als Jesus die Menschenmengen sieht, steigt er auf den Berg; seine Jünger treten zu ihm, und er lehrt sie. In neun Seligpreisungen preist er unter anderem die Armen im Geist, die Trauernden, die Sanftmütigen, die nach der Gerechtigkeit hungern, die Barmherzigen, die Frieden stiften, und die Verfolgten selig. Er nennt seine Hörer Salz der Erde und Licht der Welt. Er sei nicht gekommen, das Gesetz und die Propheten aufzuheben, sondern zu erfüllen, und ihre Gerechtigkeit müsse die der Schriftgelehrten und Pharisäer weit übertreffen. In sechs Gegenüberstellungen («Ihr habt gehört … Ich aber sage euch») spricht er über Zorn und Versöhnung, Ehebruch, Scheidung, Schwören, Vergeltung und Feindesliebe und schliesst: «Ihr sollt also vollkommen sein, wie euer himmlischer Vater vollkommen ist.»",
  "Wo de Jesus d Lüüt gseet, gaat er uf de Bärg ufe; sini Jünger chömed zu ihm, und er leert si. I nüün Säligpriisige priist er under anderem di Arme im Geischt, die, wo truured, di Sanftmüetige, die, wo nach de Grächtigkeit hungered, di Barmhärzige, die, wo Fride stifted, und di Verfolgte sälig. Er nännt sini Zuehörer Salz vo de Ärde und Liecht vo de Wält. Er seg nöd choo, zum s Gsetz und d Prophete ufzhebe, sondern zum Erfülle, und iri Grächtigkeit müess wiit über die vo de Schriftgelehrte und Pharisäer usegaa. I sächs Gägeüberstellige («Ir händ ghört … Ich aber säg eu») redt er über Zorn und Versöönig, Eebruch, Scheidig, Schwööre, Vergältig und Findesliebi und schlüüsst: «Ir söled also vollkomme sii, wie eue himmlisch Vatter vollkomme isch.»"),
 ("SUM-CH-MAT-007",
  "Jesus warnt davor, andere zu richten, und spricht vom Splitter im Auge des Bruders und vom Balken im eigenen Auge; das Heilige soll man nicht den Hunden geben und Perlen nicht vor die Schweine werfen. Er ermutigt zum Bitten, Suchen und Anklopfen, denn der Vater in den Himmeln gibt denen Gutes, die ihn bitten, und fasst zusammen: Was ihr wollt, dass euch die Menschen tun, das tut auch ihnen; das ist das Gesetz und die Propheten. Er ruft dazu auf, durch das enge Tor zu gehen, warnt vor falschen Propheten, die man an ihren Früchten erkennt, und davor, «Herr, Herr» zu sagen, ohne den Willen des Vaters zu tun. Wer seine Worte hört und tut, gleicht einem klugen Mann, der auf Felsen baut; wer sie nicht tut, einem törichten, der auf Sand baut. Die Menschenmengen sind überwältigt, denn er lehrt wie einer, der Vollmacht hat, und nicht wie ihre Schriftgelehrten.",
  "De Jesus warnt devor, anderi z richte, und redt vom Splitter im Aug vom Brueder und vom Balke im eigete Aug; s Heilig söll me nöd de Hünd gää und Perle nöd vor d Säu rüere. Er macht Muet zum Bitte, Sueche und Aachlopfe, dänn de Vatter i de Himel git dene Guets, wo en drum bitted, und fasst zäme: Was ir wänd, dass eu d Lüüt tüend, das tüend au ine; das isch s Gsetz und d Prophete. Er rüeft uf, dur s äng Tor z gaa, warnt vor falsche Prophete, wo me a irne Frücht erchännt, und devor, «Herr, Herr» z säge, ohni de Wille vom Vatter z tue. Wär sini Wort ghört und tuet, isch wie en gschiide Maa, wo uf Fels buut; wär si nöd tuet, wie en tumme, wo uf Sand buut. D Lüüt sind überwältiget, dänn er leert wie eine, wo Vollmacht hät, und nöd wie iri Schriftgelehrte."),
]


def run():
    extra = sorted((p.stem for p in (D / "translations").rglob("TRANS-MAT-00*-WORKING.json")
                    if re.fullmatch(r"TRANS-MAT-00[1-7]-\d{3}-\d{3}-(DE|GSW-ZH)-WORKING", p.stem)
                    and not p.stem.startswith("TRANS-MAT-006-005-015")),
                   key=lambda x: ("-GSW-" in x, x))
    for sid in ("STUDY-MAT-0002",):
        p = D / "studies" / f"{sid}.json"
        if p.exists() and "Matthäus 1–7" not in json.loads(p.read_text(encoding="utf-8")).get("title", ""):
            raise SystemExit(f"{sid} existiert schon mit anderem Inhalt; nicht überschreiben")
    for sid, _t, _g in SUMMARIES:
        if sid == "SUM-CH-MAT-006":
            raise SystemExit("SUM-CH-MAT-006 gehört zu vaterunser.py")
    _study.write_study({"TAGS": TAGS, "CONTEXT": CONTEXT, "FINDINGS": FINDINGS, "INTERPRETATIONS": INTERPRETATIONS,
                        "PRINCIPLES": PRINCIPLES, "APPLICATIONS": APPLICATIONS, "QUESTIONS": QUESTIONS,
                        "RELATIONS": RELATIONS, "BACKGROUND": BACKGROUND, "SUMMARIES": SUMMARIES,
                        "STUDY": ("STUDY-MAT-0002", "Matthäus 1–7 (ohne das Vaterunser 6,5–15): Studieninhalte", CHAPTERS[1],
                                  extra + [s[0] for s in SUMMARIES],
                                  ["Mundart muttersprachlich prüfen",
                                   "Fachliche Prüfung der Deutungen und des Hintergrunds",
                                   "Sekundärangaben (Josephus-, Mischna- und Qumran-Stellen; Macrobius; Philo; Plinius; "
                                   "Didache; Herodot; Platon; Isokrates; Datierungen) an Fachquellen nachprüfen",
                                   "Zählungen beruhen auf MACULA-Lemmata zum SBLGNT; andere Editionen können abweichen"])},
                       "Matthäus 1–7")


if __name__ == "__main__":
    run()
